import net.civeira.phylax.feature.oauth.delegatelogin.domain.PendingDelegation;

/**
 * Callback of delegated (SSO) providers.
 *
 * Responsibilities: - Receive the provider response (GET query for OAuth, POST form for SAML). -
 * Forward it to the authorize URL of the login that sent the browser, where it is validated.
 *
 * Design notes: - The callback only reads the pending login to know where to resume; it does not
 * trust or consume anything. Validation and single use happen in the authorize step, where the
 * browser binding cookie is sent. - Without a known state the callback answers 400. - Every value
 * is escaped and the provider data travels in the POST body, not in the URL.
 */
@Slf4j
@Path("")
@RequestScoped
@RequiredArgsConstructor
public class DelegatedAccessController {
  /**
   * Use case that coordinates delegated provider interactions.
   */
  private final DelegateLogin delegateLogin;
  /**
   * Signs the form with the device token required to open a session.
   */
  private final SecureHtmlBuilder securer;
  /**
   * JSON writer for the forwarded parameters.
   */
  private final ObjectMapper mapper;

  /**
   * Receives GET responses from delegated providers (OAuth redirect).
   *
   * @param provider provider identifier
   * @param info request URI info
   * @return page that forwards the response to the authorize step
   */
  @GET
  @Path("oauth/openid/-/delegated/authorization/{provider}")
  @Produces(AuthorizeHtml.TEXT_HTML)
  public Response entryGet(@PathParam("provider") final String provider,
      final @Context UriInfo info) {
    return forward(provider, info.getQueryParameters());
  }

  /**
   * Receives POST responses from delegated providers (SAML HTTP-POST binding, form_post).
   *
   * @param provider provider identifier
   * @param paramMap form parameters from provider
   * @return page that forwards the response to the authorize step
   */
  @POST
  @Path("oauth/openid/-/delegated/authorization/{provider}")
  @Produces(AuthorizeHtml.TEXT_HTML)
  public Response entryPost(@PathParam("provider") final String provider,
      final MultivaluedMap<String, String> paramMap) {
    return forward(provider, paramMap);
  }

  private Response forward(String provider, MultivaluedMap<String, String> params) {
    String state = Optional.ofNullable(params.getFirst("state"))
        .orElseGet(() -> params.getFirst("RelayState"));
    Optional<PendingDelegation> pending =
        delegateLogin.pending(state).filter(found -> provider.equals(found.getProvider()));
    if (pending.isEmpty()) {
      log.warn("Delegated callback for provider {} without a pending login", provider);
      return DelegatedHtml.pageHeaders(Response.status(400)
          .entity("<!doctype html><html><body><h1>Invalid or expired login</h1></body></html>")
          .type(AuthorizeHtml.TEXT_HTML)).build();
    }
    try {
      Map<String, String> fields = new LinkedHashMap<>();
      fields.put("step", "query-delegated");
      fields.put(DelegatedStep.APP_PROVIDER, provider);
      fields.put(DelegatedStep.DELEGATED_STATE, state);
      fields.put(DelegatedStep.PROVIDER_DATA, mapper.writeValueAsString(params));
      String js = securer.configureScripts(securer.addSignAndSend("sign", "form"));
      String html = "<!doctype html><html><head><meta charset=\"utf-8\"></head><body>" + js
          + "<form id=\"form\" method=\"POST\" action=\""
          + DelegatedHtml.esc(pending.get().getReturnPath()) + "\">"
          + "<input type=\"hidden\" name=\"csid\" id=\"sign\" />" + DelegatedHtml.hiddens(fields)
          + "</form></body></html>";
      return securer.secureHtmlResponse(
          DelegatedHtml.pageHeaders(Response.ok(html).type(AuthorizeHtml.TEXT_HTML)));
    } catch (JsonProcessingException ex) {
      log.error("Unable to forward delegated response for provider {}", provider, ex);
      return DelegatedHtml.pageHeaders(Response.status(500).type(AuthorizeHtml.TEXT_HTML)).build();
    }
  }
}
